34	public class Eth1DataCache {
35	  static final String CACHE_SIZE_METRIC_NAME = "eth1_block_cache_size";
36	  static final String VOTES_MAX_METRIC_NAME = "eth1_current_period_votes_max";
37	  static final String VOTES_TOTAL_METRIC_NAME = "eth1_current_period_votes_total";
38	  static final String VOTES_UNKNOWN_METRIC_NAME = "eth1_current_period_votes_unknown";
39	  static final String VOTES_CURRENT_METRIC_NAME = "eth1_current_period_votes_current";
40	  static final String VOTES_BEST_METRIC_NAME = "eth1_current_period_votes_best";
41	
42	  private final UInt64 cacheDuration;
43	  private final Eth1VotingPeriod eth1VotingPeriod;
44	
45	  private final NavigableMap<UInt64, Eth1DataAndHeight> eth1ChainCache =
46	      new ConcurrentSkipListMap<>();
47	  private final SettableGauge currentPeriodVotesTotal;
48	  private final SettableGauge currentPeriodVotesUnknown;
49	  private final SettableGauge currentPeriodVotesCurrent;
50	  private final SettableGauge currentPeriodVotesBest;
51	  private final SettableGauge currentPeriodVotesMax;
52	
53	  public Eth1DataCache(final MetricsSystem metricsSystem, final Eth1VotingPeriod eth1VotingPeriod) {
54	    this.eth1VotingPeriod = eth1VotingPeriod;
55	    cacheDuration = eth1VotingPeriod.getCacheDurationInSeconds();
56	    metricsSystem.createIntegerGauge(
57	        TekuMetricCategory.BEACON,
58	        CACHE_SIZE_METRIC_NAME,
59	        "Total number of blocks stored in the Eth1 block cache",
60	        this::size);
61	    currentPeriodVotesMax =
62	        SettableGauge.create(
63	            metricsSystem,
64	            TekuMetricCategory.BEACON,
65	            VOTES_MAX_METRIC_NAME,
66	            "Maximum number of votes that can possibly be cast in the current Eth1 voting period");
67	    currentPeriodVotesTotal =
68	        SettableGauge.create(
69	            metricsSystem,
70	            TekuMetricCategory.BEACON,
71	            VOTES_TOTAL_METRIC_NAME,
72	            "Total number of votes cast in the current Eth1 voting period");
73	    currentPeriodVotesUnknown =
74	        SettableGauge.create(
75	            metricsSystem,
76	            TekuMetricCategory.BEACON,
77	            VOTES_UNKNOWN_METRIC_NAME,
78	            "Number of votes for locally unknown Eth1 blocks in the current Eth1 voting period");
79	    currentPeriodVotesCurrent =
80	        SettableGauge.create(
81	            metricsSystem,
82	            TekuMetricCategory.BEACON,
83	            VOTES_CURRENT_METRIC_NAME,
84	            "Number of votes for the current Eth1 data in the current Eth1 voting period");
85	    currentPeriodVotesBest =
86	        SettableGauge.create(
87	            metricsSystem,
88	            TekuMetricCategory.BEACON,
89	            VOTES_BEST_METRIC_NAME,
90	            "Number of votes for the leading block in the current Eth1 voting period");
91	  }
92	
93	  public void onBlockWithDeposit(
94	      final UInt64 blockHeight, final Eth1Data eth1Data, final UInt64 blockTimestamp) {
95	    eth1ChainCache.put(blockTimestamp, new Eth1DataAndHeight(eth1Data, blockHeight));
96	    prune(blockTimestamp);
97	  }
98	
99	  public void onEth1Block(
100	      final UInt64 blockHeight, final Bytes32 blockHash, final UInt64 blockTimestamp) {
101	    final Map.Entry<UInt64, Eth1DataAndHeight> previousBlock =
102	        eth1ChainCache.floorEntry(blockTimestamp);
103	    final Eth1Data data;
104	    if (previousBlock == null) {
105	      data = new Eth1Data(Eth1Data.EMPTY_DEPOSIT_ROOT, UInt64.ZERO, blockHash);
106	    } else {
107	      data = previousBlock.getValue().getEth1Data().withBlockHash(blockHash);
108	    }
109	    eth1ChainCache.put(blockTimestamp, new Eth1DataAndHeight(data, blockHeight));
110	    prune(blockTimestamp);
111	  }
112	
113	  public Eth1Data getEth1Vote(BeaconState state) {
114	    NavigableMap<UInt64, Eth1Data> votesToConsider =
115	        getVotesToConsider(state.getSlot(), state.getGenesisTime(), state.getEth1Data());
116	    // Avoid using .values() directly as it has O(n) lookup which gets expensive fast
117	    final Set<Eth1Data> validBlocks = new HashSet<>(votesToConsider.values());
118	    final Map<Eth1Data, Eth1Vote> votes = countVotes(state);
119	
120	    Eth1Data defaultVote =
121	        votesToConsider.isEmpty() ? state.getEth1Data() : votesToConsider.lastEntry().getValue();
122	
123	    Optional<Eth1Data> vote =
124	        votes.entrySet().stream()
125	            .filter(entry -> validBlocks.contains(entry.getKey()))
126	            .max(Map.Entry.comparingByValue())
127	            .map(Map.Entry::getKey);
128	
129	    return vote.orElse(defaultVote);
130	  }
131	
132	  public Collection<Eth1Data> getAllEth1Blocks() {
133	    return this.eth1ChainCache.values().stream().map(Eth1DataAndHeight::getEth1Data).toList();
134	  }
135	
136	  public void updateMetrics(final BeaconState state) {
137	    final Eth1Data currentEth1Data = state.getEth1Data();
138	    // Avoid using .values() directly as it has O(n) lookup which gets expensive fast
139	    final Set<Eth1Data> knownBlocks =
140	        new HashSet<>(
141	            getVotesToConsider(state.getSlot(), state.getGenesisTime(), currentEth1Data).values());
142	    Map<Eth1Data, Eth1Vote> votes = countVotes(state);
143	
144	    currentPeriodVotesMax.set(eth1VotingPeriod.getTotalSlotsInVotingPeriod(state.getSlot()));
145	    currentPeriodVotesTotal.set(state.getEth1DataVotes().size());
146	    currentPeriodVotesUnknown.set(
147	        votes.keySet().stream().filter(votedBlock -> !knownBlocks.contains(votedBlock)).count());
148	    currentPeriodVotesCurrent.set(
149	        votes.getOrDefault(currentEth1Data, new Eth1Vote(0)).getVoteCount());
150	
151	    currentPeriodVotesBest.set(
152	        votes.values().stream()
153	            .max(Comparator.naturalOrder())
154	            .map(Eth1Vote::getVoteCount)
155	            .orElse(0));
156	  }
157	
158	  protected Map<Eth1Data, Eth1Vote> countVotes(final BeaconState state) {
159	    Map<Eth1Data, Eth1Vote> votes = new HashMap<>();
160	    int i = 0;
161	    for (Eth1Data eth1Data : state.getEth1DataVotes()) {
162	      final int currentIndex = i;
163	      votes.computeIfAbsent(eth1Data, key -> new Eth1Vote(currentIndex)).incrementVotes();
164	      i++;
165	    }
166	    return votes;
167	  }
