169	  protected Optional<Eth1DataAndHeight> getEth1DataAndHeight(final Eth1Data eth1Data) {
170	    return eth1ChainCache.values().stream()
171	        .filter(eth1DataAndHeight -> eth1DataAndHeight.getEth1Data().equals(eth1Data))
172	        .f
