14	package tech.pegasys.teku.infrastructure.async.runloop;
15	
16	import static org.assertj.core.api.Assertions.assertThat;
17	import static org.mockito.Mockito.atLeastOnce;
18	import static org.mockito.Mockito.mock;
19	import static org.mockito.Mockito.never;
20	import static org.mockito.Mockito.times;
21	import static org.mockito.Mockito.verify;
22	import static org.mockito.Mockito.verifyNoMoreInteractions;
23	import static org.mockito.Mockito.when;
24	
25	import java.time.Duration;
26	import org.junit.jupiter.api.BeforeEach;
27	import org.junit.jupiter.api.Test;
28	import tech.pegasys.teku.infrastructure.async.SafeFuture;
29	import tech.pegasys.teku.infrastructure.async.StubAsyncRunner;
