40	      final TekuConfiguration tekuConfig, final ServiceConfig serviceConfig) {
41	    // Note services will be started in the order they are added here.
42	    services.add(
43	        new StorageService(
44	            serviceConfig,
45	            tekuConfig.storageConfiguration(),
46	            tekuConfig
47	                .powchain()
48	                .getDepositTreeSnapshotConfiguration()
49	                .isBundledDepositSnapshotEnabled(),
50	            tekuConfig.metricsConfig().isBlobSidecarsStorageCountersEnabled(),
51	            tekuConfig.metricsConfig().isDataColumnSidecarsStorageCountersEnabled(),
52	            tekuConfig.beaconChain().eth2NetworkConfig().getEth2Network()));
53	    Optional<ExecutionWeb3jClientProvider> maybeExecutionWeb3jClientProvider = Optional.empty();
54	    if (tekuConfig.executionLayer().isEnabled()) {
55	      // Need to make sure the execution engine is listening before starting the beacon chain
56	      final ExecutionLayerService executionLayerService =
57	          ExecutionLayerService.create(
58	              serviceConfig,
59	              tekuConfig.executionLayer(),
60	              tekuConfig.eth2NetworkConfiguration().getSpec());
61	      services.add(executionLayerService);
62	      maybeExecutionWeb3jClientProvider = executionLayerService.getEngineWeb3jClientProvider();
63	    }
64	    final BeaconChainService beaconChainService =
65	        new BeaconChainService(serviceConfig, tekuConfig.beaconChain());
66	    services.add(beaconChainService);
67	    final NetworkConfig networkConfig = tekuConfig.network();
68	    services.add(
69	        new NatService(
70	            tekuConfig.natConfiguration(),
71	            networkConfig.getListenPort(),
72	            networkConfig.getNetworkInterfaces().size() == 2
73	                // IPv4 and IPv6 (dual-stack)
74	                ? Optional.of(networkConfig.getListenPortIpv6())
75	                : Optional.empty(),
76	            tekuConfig.discovery().isDiscoveryEnabled()));
77	    // making it a Supplier ensures that BeaconChainService has been started and RecentChainData has
78	    // been initialized when `get()` is called
79	    final Supplier<Optional<BeaconState>> finalizedStateSupplier =
80	        () -> {
81	          final RecentChainData recentChainData =
82	              beaconChainService.getBeaconChainController().getRecentChainData();
83	          if (recentChainData.isPreGenesis()) {
84	            return Optional.empty();
85	          }
86	          return Optional.of(recentChainData.getStore().getLatestFinalized().getState());
87	        };
88	    powchainService(
89	            tekuConfig, serviceConfig, maybeExecutionWeb3jClientProvider, finalizedStateSupplier)
90	        .ifPresent(services::add);
91	
92	    final Optional<SlashingRiskAction> maybeValidatorSlashedAction =
93	        tekuConfig.validatorClient().getValidatorConfig().isShutdownWhenValidatorSlashedEnabled()
94	            ? Optional.of(new SlashedValidatorShutDown())
95	            : Optional.empty();
96	
97	    services.add(
98	        ValidatorClientService.create(
99	            serviceConfig,
100	            tekuConfig.validatorClient(),
101	            new DoppelgangerDetectionShutDown(),
102	            maybeValidatorSlashedAction));
103	  }
