105	  private Optional<PowchainService> powchainService(
106	      final TekuConfiguration tekuConfig,
107	      final ServiceConfig serviceConfig,
108	      final Optional<ExecutionWeb3jClientProvider> maybeExecutionWeb3jClientProvider,
109	      final Supplier<Optional<BeaconState>> finalizedStateSupplier) {
110	    if (tekuConfig.beaconChain().interopConfig().isInteropEnabled()
111	        || (!tekuConfig.powchain().isEnabled() && maybeExecutionWeb3jClientProvider.isEmpty())) {
112	      return Optional.empty();
113	    }
114	    if (!tekuConfig.powchain().isDepositContractLogsSyncingEnabled()) {
115	      // PowchainService is only used for deposit contract logs syncing, so no need to initialize it
116	      // if disabled
117	      EVENT_LOG.depositContractLogsSyncingDisabled();
118	      return Optional.empty();
119	    }
120	    final PowchainService powchainService =
121	        new PowchainService(
122	            serviceConfig,
123	            tekuConfig.powchain(),
124	            maybeExecutionWeb3jClientProvider,
125	            finalizedStateSupplier);
126	    serviceConfig.getEventChannels().subscribe(FinalizedCheckpointChannel.class, powchainService);
127	    return Optional.of(powchainService);
128	  }
